# v15.58: month selector state + order, main card layout and flip, Accounts action row, Transactions tab name, Spent Each Day softness
from playwright.sync_api import sync_playwright
CSV='/home/claude/Transactions.csv'
def ok(n,c): print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as p:
    b=p.chromium.launch()
    for W in (390,320):
        ctx=b.new_context(viewport={'width':W,'height':844},service_workers='block'); pg=ctx.new_page(); errs=[]; pg.on('pageerror',lambda e:errs.append(str(e)))
        pg.goto('http://localhost:8123/'); pg.wait_for_selector('#first-file',state='attached'); pg.set_input_files('#first-file',CSV); pg.wait_for_selector('#setup',timeout=20000)
        pg.goto('http://localhost:8123/#/home'); pg.wait_for_timeout(1500)
        g=pg.evaluate("(()=>{const r=s=>document.querySelector(s).getBoundingClientRect();return {ms:r('.monthsel').right,eye:r('.hact [data-act=eye]').right,eyeL:r('.hact [data-act=eye]').left,msL:r('.monthsel').left,vw:innerWidth,sw:document.documentElement.scrollWidth}})()")
        ok('%d: month selector is rightmost, eye just left of it %s'%(W,g), g['ms']>g['eye'] and g['eye']<=g['msL']+1 and g['ms']>g['vw']-40 and g['sw']<=g['vw'])
        pg.click('.mscard'); pg.wait_for_timeout(200); ok('%d: opens'%W, pg.locator('.mspanel:visible').count()==1)
        pg.click('.mscard'); pg.wait_for_timeout(200); ok('%d: same arrow closes it'%W, pg.locator('.mspanel:visible').count()==0 and pg.get_attribute('.mscard','aria-expanded')=='false')
        pg.click('.mscard'); pg.wait_for_timeout(200)
        pg.click('.msyear [data-d="-1"]'); pg.wait_for_timeout(150); y1=pg.inner_text('.msyear b')
        pg.click('.msyear [data-d="-1"]'); pg.wait_for_timeout(150); y2=pg.inner_text('.msyear b')
        ok('%d: previous-year arrow steps back repeatedly %s %s'%(W,y1,y2), int(y2)==int(y1)-1 and pg.locator('.mspanel:visible').count()==1)
        pg.evaluate("window.dispatchEvent(new Event('sukli-render'))"); pg.wait_for_timeout(400)
        ok('%d: a screen redraw keeps the picker open'%W, pg.locator('.mspanel:visible').count()==1 and pg.get_attribute('.mscard','aria-expanded')=='true')
        pg.evaluate("window.scrollTo(0,0)")
        # main card
        c=pg.evaluate("(()=>{const q=s=>document.querySelector(s),cs=e=>getComputedStyle(e);const lab=q('.sc-front .sc-lab');return {h:q('.main-home-card').getBoundingClientRect().height,lfs:parseFloat(cs(lab).fontSize),rows:q('.sc-front .sc-rows').getBoundingClientRect().bottom,card:q('.main-home-card').getBoundingClientRect().bottom,bt:cs(q('.sc-front .sc-rows')).borderTopWidth,bl:cs(q('.sc-front .sc-row:last-child')).borderLeftWidth,txt:q('.sc-front .sc-rows').innerText,front:q('.sc-front .sc-net').innerText}})()")
        print(c)
        ok('%d: height up, label small, no dividers, Expenses'%W, c['h']>=190 and c['lfs']<=12.1 and c['bt']=='0px' and c['bl']=='0px' and 'Expenses' in c['txt'] and 'Expense\n' not in c['txt'].replace('Expenses','')) 
        ok('%d: rows sit near bottom border'%W, c['card']-c['rows']<=28)
        ok('%d: Net income by default'%W, 'Net income' in c['front'] and pg.locator('.main-home-card.flipped').count()==0)
        h0=pg.evaluate("document.querySelector('.main-home-card .sc-front').getBoundingClientRect().height"); y0=pg.evaluate("document.querySelector('.main-home-card .sc-front').getBoundingClientRect().top+scrollY")
        pg.click('.main-home-card:not(.flipped) .sc-front .sc-swap, .main-home-card.flipped .sc-back .sc-swap'); pg.wait_for_timeout(120)
        mid=pg.evaluate("getComputedStyle(document.querySelector('.sc-inner')).transform"); ok('%d: it rotates (mid-animation transform %s)'%(W,mid[:30]), mid!='none' and mid!='matrix(1, 0, 0, 1, 0, 0)')
        pg.wait_for_timeout(800)
        h1=pg.evaluate("document.querySelector('.main-home-card .sc-front').getBoundingClientRect().height")
        ok('%d: no layout shift on flip'%W, abs(h1-h0)<0.5 and pg.evaluate("document.documentElement.scrollWidth")<=W)
        t=pg.evaluate("document.querySelector('.sc-back').innerText"); ok('%d: Net worth, Assets, Liabilities %r'%(W,t), 'Net worth' in t and 'Assets' in t and 'Liabilities' in t)
        ok('%d: hidden face is inert'%W, pg.evaluate("document.querySelector('.sc-front').inert"))
        pg.evaluate("window.dispatchEvent(new Event('sukli-render'))"); pg.wait_for_timeout(400)
        ok('%d: redraw keeps the flipped side without animating'%W, pg.locator('.main-home-card.flipped').count()==1)
        pg.click('.main-home-card:not(.flipped) .sc-front .sc-swap, .main-home-card.flipped .sc-back .sc-swap'); pg.wait_for_timeout(900); ok('%d: flips back'%W, pg.locator('.main-home-card.flipped').count()==0)
        pg.reload(); pg.wait_for_timeout(1500); ok('%d: reopened app shows Net income'%W, pg.locator('.main-home-card.flipped').count()==0)
        r=pg.evaluate("(()=>{const w=document.querySelector('.week'),s=getComputedStyle(w);return [s.borderRadius,s.boxShadow!=='none']})()"); ok('%d: Spent Each Day soft %s'%(W,r), r[0]=='24px' and r[1])
        # tab name + accounts
        ok('%d: tab says Transactions'%W, 'Transactions' in pg.inner_text('#tabs'))
        pg.goto('http://localhost:8123/#/accounts'); pg.wait_for_timeout(1200)
        a=pg.evaluate("(()=>{const r=s=>document.querySelector(s).getBoundingClientRect();const eye=r('.top [data-act=eye]'),row=r('.actrow');return {eyeB:eye.bottom,rowT:row.top,rowR:row.right,vw:innerWidth,sw:document.documentElement.scrollWidth,btns:[...document.querySelectorAll('.actrow .btn')].map(b=>b.getBoundingClientRect().right)}})()")
        ok('%d: Accounts eye above the action buttons, no overflow %s'%(W,a), a['eyeB']<=a['rowT']+1 and a['sw']<=a['vw'] and max(a['btns'])<=a['vw'])
        ok('%d: no page errors %s'%(W,errs), not errs)
        ctx.close()
